package main

import "testing"

{{code}}

func TestNormalizePathAbsolute(t *testing.T) {
	cases := map[string]string{
		"/a//b/./c/../d": "/a/b/d",
		"/../../a":         "/a",
		"///":             "/",
	}
	for input, want := range cases {
		if got := NormalizePath(input); got != want {
			t.Fatalf("NormalizePath(%q) = %q, want %q", input, got, want)
		}
	}
}

func TestNormalizePathRelative(t *testing.T) {
	cases := map[string]string{
		"./a/./b": "a/b",
		"a/b/../..": ".",
		"../../a": "../../a",
	}
	for input, want := range cases {
		if got := NormalizePath(input); got != want {
			t.Fatalf("NormalizePath(%q) = %q, want %q", input, got, want)
		}
	}
}

package main

import "testing"

{{code}}

func TestParseSizeValid(t *testing.T) {
	cases := map[string]uint64{
		"42": 42,
		"2 KB": 2 * 1024,
		"3mb": 3 * 1024 * 1024,
		"1Gb": 1024 * 1024 * 1024,
	}
	for input, want := range cases {
		got, err := ParseSize(input)
		if err != nil || got != want {
			t.Fatalf("ParseSize(%q) = (%d, %v), want %d nil", input, got, err, want)
		}
	}
}

func TestParseSizeInvalid(t *testing.T) {
	for _, input := range []string{"", "-1KB", "1.5MB", "4TB"} {
		if _, err := ParseSize(input); err == nil {
			t.Fatalf("ParseSize(%q) succeeded", input)
		}
	}
}

package main

import (
	"reflect"
	"testing"
)

{{code}}

func TestMergeIntervals(t *testing.T) {
	got := MergeIntervals([]Interval{{5, 3}, {4, 8}, {20, 21}, {22, 22}})
	want := []Interval{{3, 8}, {20, 22}}
	if !reflect.DeepEqual(got, want) {
		t.Fatalf("got %#v, want %#v", got, want)
	}
}

func TestMergeIntervalsEmptyAndSeparate(t *testing.T) {
	if got := MergeIntervals(nil); len(got) != 0 {
		t.Fatalf("empty got %#v", got)
	}
	got := MergeIntervals([]Interval{{1, 1}, {3, 3}})
	want := []Interval{{1, 1}, {3, 3}}
	if !reflect.DeepEqual(got, want) {
		t.Fatalf("got %#v, want %#v", got, want)
	}
}

