func TestTopKWords(t *testing.T) {
	got := TopKWords([]string{" Go ", "rust", "go", "Rust", "zig", "go"}, 2)
	want := []WordCount{{"go", 3}, {"rust", 2}}
	if !reflect.DeepEqual(got, want) {
		t.Fatalf("got %#v, want %#v", got, want)
	}
}

func TestTopKWordsZeroAndTies(t *testing.T) {
	if got := TopKWords([]string{"b", "a", "B", "a"}, 0); len(got) != 0 {
		t.Fatalf("zero got %#v", got)
	}
	got := TopKWords([]string{"b", "a", "B", "a"}, 3)
	want := []WordCount{{"a", 2}, {"b", 2}}
	if !reflect.DeepEqual(got, want) {
		t.Fatalf("got %#v, want %#v", got, want)
	}
}

